(function(){"use strict";self.onmessage=async function(i){const{file:r}=i.data;if(!r){self.postMessage({type:"error",message:"no file"});return}try{const e=r.size,c=4*1024*1024,o=[];let s=0;for(;s<e;){const t=Math.min(s+c,e);o.push(await r.slice(s,t).arrayBuffer()),s=t,self.postMessage({type:"progress",pct:e===0?100:Math.floor(s*100/e)})}const n=new Uint8Array(e);let a=0;for(const t of o)n.set(new Uint8Array(t),a),a+=t.byteLength;const f=await crypto.subtle.digest("SHA-256",n),g=Array.from(new Uint8Array(f),t=>t.toString(16).padStart(2,"0")).join("");self.postMessage({type:"done",hash:g})}catch(e){self.postMessage({type:"error",message:String(e&&e.message||e)})}}})();
